          env.DB.prepare("INSERT INTO market_listings(seller_telegram_id,plate,region,rarity,cls,value,asking_price,status,created_at) SELECT ?,?,?,?,?,?,?,'active',? WHERE changes()=1").bind(telegramId,item.plate,item.region,item.rarity,item.cls,Number(item.value)||0,price,now)
